mapper.sql:
WHERE a.achievement_type = 'lecture-improvements'
  AND a.deleted_yn = 'N'

    AND a.management_no = #{criteria.managementNo}


    AND u.login_id ILIKE CONCAT('%', #{criteria.teacherName}, '%')


    AND a.management_item_code = #{criteria.managementItemCode}


    AND a.achievement_status = #{criteria.achievementStatus}

AND (
    FALSE
    OR TRUE
    OR a.teacher_user_id = #{userId}

        OR EXISTS (
            SELECT 1
            FROM organization_user_mappings rm
            JOIN organization_user_mappings tm ON tm.organization_code = rm.organization_code
            WHERE rm.user_id = #{userId}
              AND rm.status = 'ACTIVE'
              AND tm.user_id = a.teacher_user_id
              AND tm.status = 'ACTIVE'
        )


        OR EXISTS (
            SELECT 1
            FROM evaluation_organization_mappings pm
            JOIN organization_user_mappings tm ON tm.organization_code = pm.organization_code
            WHERE pm.user_id = #{userId}
              AND pm.business_type = 'FACULTY_ACHIEVEMENT'
              AND pm.data_scope IN ('DEPARTMENT', 'COLLEGE', 'BUSINESS', 'ALL')
              AND tm.user_id = a.teacher_user_id
              AND tm.status = 'ACTIVE'
        )

)

mapper.select:
SELECT 


ORDER BY a.achievement_date DESC, a.achievement_id DESC
LIMIT #{criteria.pageSize}
OFFSET #{criteria.offset}

mapper.insert:
INSERT INTO education_achievements (
    management_no, achievement_type, teacher_user_id, organization_code,
    evaluation_year, management_item_code, achievement_date, attachment_ids,
    created_by, updated_by, request_id
)
VALUES (
    #{managementNo}, 'lecture-improvements', #{owner}, #{organization},
    #{year}, #{body.managementItemCode}, #{body.achievementDate}, CAST(#{attachments} AS jsonb),
    #{actor}, #{actor}, #{requestId}
)

INSERT INTO data_change_histories (
    target_business, target_key, change_type, field_name,
    before_value, after_value, changed_by, change_reason, request_id
)
VALUES (
    'education_achievements', CAST(#{id} AS varchar), #{changeType}, 'snapshot',
    #{before,jdbcType=VARCHAR}, #{after}, #{actor}, '강의개선 실적 저장', #{requestId}
)
